    # diagonal colors to establish the period.
    period = 17
    residues = {d % period: color for d, color in known.items()}
    ds = sorted(known)
    result = []
    for r in range(n):
        row_out = []
        for c in range(m):
            d = c - r
            if d in known:
                color = known[d]
            elif d % period in residues:
                color = residues[d % period]
            else:
                nearest = min(ds, key=lambda x: abs(x - d))
                color = known[nearest]
            row_out.append(color)
        result.append(row_out)
