def transform(grid):
    n, m = len(grid), len(grid[0])
    # Read the colors of the diagonal bands, ordered from left to right
    # by their offset, and repeat that diagonal pattern.
    bands = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                bands[c - r] = value

    offsets = sorted(bands)
    colors = [bands[d] for d in offsets]
    period = len(colors)
    start = offsets[0]
    return [[colors[(c - r - start) % period] for c in range(m)]
            for r in range(n)]
