def transform(grid):
    h, w = len(grid), len(grid[0])
    bands = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                bands[c - r] = value

    # Find the smallest repeating diagonal period consistent with every
    # observed colored band.
    offsets = list(bands)
    period = max(h, w)
    for p in range(1, max(h, w) + 1):
        consistent = True
        for i, d in enumerate(offsets):
            for e in offsets[i + 1:]:
                if (d - e) % p == 0 and bands[d] != bands[e]:
                    consistent = False
                    break
            if not consistent:
                break
        if consistent:
            period = p
            break

    # Use each observed stripe to define its residue class; for unobserved
    # classes, extend the nearest observed stripe.
    classes = {}
    for d, value in bands.items():
        classes[d % period] = value
    observed = sorted(bands)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            d = c - r
            if d % period in classes:
                value = classes[d % period]
            else:
                nearest = min(observed, key=lambda x: abs(x - d))
                value = bands[nearest]
            row.append(value)
        out.append(row)
    return out
